//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::hash::string_hash`; the
//! native twin is `benches/native/Bench/StringHash.lean`.
//! the operand passes through black_box on the Rust side (no hoisting)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::hash;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &String, n: u64) -> u64 {
    let s = inp.as_bytes();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, hash::string_hash(black_box(s)));
    }
    acc
}

fn main() {
    run(|| mixed(), kernel)
}
